// Sample trips for the routing tests. They used to ship in the app as demo data;
// the app no longer has any trips until a real trip source exists.
// ignore_for_file: lines_longer_than_80_chars
import 'dart:convert';

import 'package:latlong2/latlong.dart';
import 'package:ner_logistics/mock_data/mock_route_scenarios.dart';
import 'package:ner_logistics/services/routing/osrm_models.dart';
import 'package:ner_logistics/services/routing/trip_plan.dart';

/// TRP-2291 · Guwahati depot → Sonapur via Shillong and Jowai (NH-6).
/// The hazard sits on the NH-6 cut slopes west of Jowai, where OSRM finds a
/// real road detour (checked against the public server, Sep 2026).
const fieldTripScenario = RouteScenario(
  id: 'TRP-2291',
  originLabel: 'Guwahati Depot',
  destinationLabel: 'Sonapur',
  waypoints: [LatLng(26.1445, 91.7362), LatLng(25.0455, 92.4205)],
  hazardPoint: LatLng(25.4829, 92.1977),
  hazardLabel: 'Predicted landslide',
  hazardConfidence: 78,
  cautionPoint: LatLng(25.5155, 92.1574),
  cautionLabel: 'Wet slope, reduce speed',
);

/// ASN-4821 · Guwahati Medical Depot → Nongpoh Civil Hospital (NH-6).
const riderTripScenario = RouteScenario(
  id: 'TRP-R-4821',
  originLabel: 'Guwahati Medical Depot',
  destinationLabel: 'Nongpoh Civil Hospital',
  waypoints: [LatLng(26.1545, 91.7700), LatLng(25.9095, 91.8768)],
  vehicleFraction: 0.58,
);

class TripFixtures {
  TripFixtures._();

  static TripRoutePlan fieldPlan() => _plan(fieldTripScenario, kFieldTripRouteJson);
  static TripRoutePlan riderPlan() => _plan(riderTripScenario, kRiderTripRouteJson);

  static TripDetourPlan fieldDetour() => TripDetourPlan(
        detourFromJson(jsonDecode(kFieldTripDetourJson) as Map<String, dynamic>),
        live: false,
        advanceM: fieldTripScenario.postRerouteAdvanceM,
      );

  static TripRoutePlan _plan(RouteScenario s, String json) => TripRoutePlan.fromRoute(
      s, OsrmRoute.fromJson(jsonDecode(json) as Map<String, dynamic>),
      live: false);
}

